--liquibase formatted sql

--changeset sam:260-ccnl-preavviso
--comment: Termini di preavviso per CCNL, gruppo di livelli e fascia di anzianita' (decisione 162): solo i CCNL con
--comment: valori concordi su due fonti; gli altri non hanno righe e il preavviso risulta "non verificato".
CREATE TABLE ccnl_preavviso (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ccnl_codice          VARCHAR(50)  NOT NULL,
    ordine               INTEGER      NOT NULL,
    livelli              VARCHAR(200) NOT NULL,
    descrizione_livelli  VARCHAR(200) NOT NULL,
    oltre_anni           INTEGER      NOT NULL,
    dimissioni_mesi      INTEGER      NOT NULL,
    dimissioni_giorni    INTEGER      NOT NULL,
    licenziamento_mesi   INTEGER      NOT NULL,
    licenziamento_giorni INTEGER      NOT NULL,
    riferimento          VARCHAR(500),
    CONSTRAINT fk_ccnl_preavviso_ccnl FOREIGN KEY (ccnl_codice) REFERENCES ccnl (codice),
    CONSTRAINT uk_ccnl_preavviso UNIQUE (ccnl_codice, ordine),
    CONSTRAINT ck_ccnl_preavviso_durate CHECK (oltre_anni >= 0 AND dimissioni_mesi >= 0 AND dimissioni_giorni >= 0
        AND licenziamento_mesi >= 0 AND licenziamento_giorni >= 0
        AND dimissioni_mesi + dimissioni_giorni > 0 AND licenziamento_mesi + licenziamento_giorni > 0)
);

--changeset sam:261-ccnl-preavviso-valori
--comment: Valori in mesi e giorni di calendario. oltre_anni: 0 = fino a 5 anni, 5 = oltre 5 e fino a 10, 10 = oltre 10.
